      SUBROUTINE MROTCC     CALCULATES MISALIGNMENT ROTATION MATRIXCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM8K.CIN'CC     LOCAL VARIABLESC      EQUIVALENCE  (RX,VROT(1)), (RY,VROT(2)), (RZ,VROT(3))CC--------------------------------------------------------------      SN = SNM      ZN = ZNMC      RM(1,1) = - (1.0 - RX**2)*ZN      RM(1,2) = - RZ*SN + RX*RY*ZN      RM(1,3) = RY*SN + RX*RZ*ZN      RM(2,1) = RZ*SN + RX*RY*ZN      RM(2,2) = - (1.0 - RY**2)*ZN      RM(2,3) = - RX*SN + RY*RZ*ZN      RM(3,1) = - RY*SN + RX*RZ*ZN      RM(3,2) = RX*SN + RY*RZ*ZN      RM(3,3) = - (1.0 - RZ**2)*ZN      RETURN      END